from PIL import Image
img = Image.open('/app/output/final_poster.png')
# Scan row 1 area for non-background pixels
bg = (3, 4, 9)
for y in range(669, 730):
    for x in range(180, 220):
        p = img.getpixel((x, y))
        if p != bg and p[0] > 20:
            print(f'  ({x},{y}): {p}')
            break
    else:
        continue
    break

# Scan more broadly in row 1
found = False
for y in range(670, 700):
    row_pixels = []
    for x in range(183, 300):
        p = img.getpixel((x, y))
        if p != bg and sum(p) > 30:
            row_pixels.append((x, p))
    if row_pixels:
        print(f'y={y}: {row_pixels[:5]}')
        found = True
if not found:
    print('No bright text found in row 1 area')

# Check if the header text (drawn before glow blend) was darkened
print()
print('Checking title area for darkening...')
for y in range(125, 135):
    for x in range(115, 300):
        p = img.getpixel((x, y))
        if sum(p) > 100:
            print(f'Title pixel at ({x},{y}): {p}')
            break
"

